create table if not exists daily_stats (
    day date primary key,
    minutes int not null default 0,
    wpm numeric(5, 1) not null default 0,
    accuracy numeric(4, 3) not null default 0
);

create index idx_daily_stats_wpm on daily_stats (wpm desc);

insert into sessions (id, mode, language, started_at)
values (gen_random_uuid(), 'code', 'rust', now())
returning id, started_at;
